def main():
    out=Path(sys.argv[1]) if len(sys.argv)>1 else HERE/'presets'
    out.mkdir(parents=True,exist_ok=True)
    for meta in PATCHES:(out/(meta['name']+'.aif')).write_bytes(aifc(meta))
    print(f'{len(PATCHES)} normal Oxbow presets in {out}; no internal programs')
if __name__=='__main__':main()
